import{_ as a,o,c as i,a0 as s}from"./chunks/framework.CNDWyMYS.js";const p=JSON.parse('{"title":"Manifest file format","description":"","frontmatter":{},"headers":[],"relativePath":"manifest_file_format.md","filePath":"manifest_file_format.md"}'),t={name:"manifest_file_format.md"};function n(r,e,c,d,l,f){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="manifest-file-format" tabindex="-1">Manifest file format <a class="header-anchor" href="#manifest-file-format" aria-label="Permalink to &quot;Manifest file format&quot;">​</a></h1><p>A manifest file describes files contained in a rocks tree or server. Each rocks tree or server has a <code>manifest</code> file in its root. Rocks servers may also have versioned manifests (e.g. <code>manifest-5.1</code> for Lua 5.1) and compressed manifests (e.g. <code>manifest-5.1.zip</code>). These must match the contents of the uncompressed manifest.</p><p>Like a rockspec, a manifest file contains a Lua program setting several globals. Three of them are mandatory:</p><ul><li><code>repository</code>: a table where each key is a package name and its value is a table describing versions of the package hosted on a server or installed in a rocks tree. <ul><li><code>repository[package_name]</code>: a table where each key is a package version (including revision, e.g. <code>1.0.0-1</code>) and its value provides information for that version. <ul><li><code>repository[package_name][package_version]</code>: a list of tables containing several fields: <ul><li><code>arch</code>: architecture of the rock as a string. Always set to <code>installed</code> in rock tree manifests.</li><li><code>modules</code> (only for rock tree manifests): a table mapping module names to paths under installation directory for Lua or C modules.</li><li><code>commands</code> (only for rock tree manifests): a table mapping script names to paths under installation directory for binaries.</li><li><code>dependencies</code> (only for rock tree manifests): a table mapping names of packages the rock depends on (perhaps indirectly) to versions of installed packages satisfying the dependency.</li></ul></li></ul></li></ul></li><li><code>modules</code>: empty table in rock server manifests (may change in future releases). In rock tree manifests it&#39;s a table mapping module names to lists of packages and versions providing that module. Each value in the list is a string in <code>module/version</code> format (e.g. <code>foo/1.0.0-1</code>).</li><li><code>commands</code>: empty table in rock server manifests (may change in future releases). In rock tree manifests it&#39;s a table mapping script names to lists of packages and versions providing that script, using same format as <code>modules</code> table.</li><li><code>dependencies</code> (only for rock tree manifests): a table containing precomputed dependency information to be used by <code>luarocks.loader</code>. Each key is a package name. <ul><li><code>dependencies[package_name]</code>: A table where each key is a version (with revision) and its value describes dependencies of that version of the package. <ul><li><code>dependencies[package_name][package_version]</code>: An array of direct dependencies represented as tables with the following fields: <ul><li><code>name</code>: name of the rock that is depended on.</li><li><code>constraints</code>: an array of parsed version constraints. Each constraint is represented as a table with fields: <ul><li><code>op</code>: an operator as a string (e.g. <code>&gt;=</code>).</li><li><code>version</code>: version to the right of the operator as an array of parts, e.g. <code>{1, 0, 0}</code> for <code>1.0.0</code>. It also contains version as a string in <code>string</code> field and may contain revision in <code>revision</code> field.</li></ul></li></ul></li></ul></li></ul></li></ul>',4)])])}const h=a(t,[["render",n]]);export{p as __pageData,h as default};
